interface.signature:
POST /api/v1/users/{user_id}/roles Authorization: Bearer {jwt_token} Content-Type: application/json
Request Body: { "tenant_id": "uuid", "role": "super_admin" | "tenant_admin" | "developer" | "operator" | "viewer" }
Response (201 Created): { "id": "uuid", "user_id": "uuid", "tenant_id": "uuid", "role": "string", "assigned_at": "datetime", "assigned_by": "uuid" }

DELETE /api/v1/users/{user_id}/roles/{role_id}
Authorization: Bearer {jwt_token}

Response: 204 No Content (success) or 400 Bad Request (last super_admin)

GET /api/v1/roles
Authorization: Bearer {jwt_token}

Response (200 OK):
[
  {
    "role": "super_admin",
    "display_name": "Super Admin",
    "description": "Full system access across all tenants",
    "level": 1
  },
  ...
]

class RoleAssignmentCreate(BaseModel):
    tenant_id: UUID
    role: RoleEnum

    @validator('role')
    def validate_role(cls, v):
        if v not in RoleEnum:
            raise ValueError(f"Invalid role. Must be one of: {list(RoleEnum)}")
        return v
